async function refreshSharedData(force=false){
  const response=await fetch('./api/data',{cache:'no-store'});
  if(!response.ok)throw new Error('Servidor indisponível');
  const payload=await response.json();
  const remoteRevision=Number(payload.revision||0);
  const changedByRevision=remoteRevision>state.revision;
  const changedByDate=Boolean(payload.updatedAt&&payload.updatedAt!==state.updatedAt);
  if(payload.data&&(force||changedByRevision||changedByDate)){
    state.data=normalizeTeamNames(normalizeSharedData(payload.data));
    state.revision=remoteRevision;
    state.updatedAt=payload.updatedAt||null;
    localStorage.setItem('proelium-data',JSON.stringify(state.data));
    render();
  }else{
    state.revision=remoteRevision;
    state.updatedAt=payload.updatedAt||state.updatedAt;
  }
  state.lastSyncAt=new Date().toISOString();
  document.body.dataset.shared='true';
  updateSharedStatus();
  return payload;
}
async function connectSharedData(){
  if(location.protocol==='file:')return;
  if(!await authenticate())return;
  try{
    const payload=await refreshSharedData(true);
    const quoteTotalsChanged=(state.data.quotes||[]).some(quote=>Math.abs(Number(quote.value||0)-Number(quoteTotals(quote.id).price||0))>.005);
    if(quoteTotalsChanged||!payload.data||!payload.data.collaborators?.length||!payload.data.evaluations?.length||payload.data.collaborators.some(person=>person.name==='Colaborador'||person.name==='Colaborador técnico')||embraceCatalogSyncNeeded){await persist();embraceCatalogSyncNeeded=false}
    const events=new EventSource('./api/events');
    events.addEventListener('presence-updated',event=>{try{updatePresencePanel(JSON.parse(event.data).users)}catch{}});
    events.addEventListener('collaboration-request',event=>{try{const request=JSON.parse(event.data),message=`${request.from?.name||'Alguém'} quer colaborar: ${request.message}`;toast(message);if('Notification' in window&&Notification.permission==='granted')new Notification('Pedido de colaboração Proelium',{body:message})}catch{}});
    events.addEventListener('assistance-request',event=>{try{const request=JSON.parse(event.data),message=`${request.from?.name||'Alguém'} pediu auxílio: ${request.message}`;toast(message);if('Notification' in window&&Notification.permission==='granted')new Notification('Pedido de auxílio Proelium',{body:message})}catch{}});
    if('Notification' in window&&Notification.permission==='default'&&authenticatedUser?.role==='admin')Notification.requestPermission().catch(()=>{});
    startPresence();
    events.addEventListener('data-updated',async event=>{
      const update=JSON.parse(event.data);
      if(Number(update.revision)>state.revision&&!state.syncing){
        try{await refreshSharedData();toast('Dados atualizados por outro aparelho.')}catch{}
      }
    });
    events.onerror=()=>{document.body.dataset.shared='reconnecting';updateSharedStatus()};
    events.onopen=()=>{document.body.dataset.shared='true';updateSharedStatus()};
    setInterval(()=>refreshSharedData().catch(()=>{}),5000);
    document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshSharedData().catch(()=>{})});
  }catch{toast('Modo local: dados ainda não estão compartilhados.')}
}
