const financialCategories=['Materiais','Mão de obra','Logística','Serviços terceirizados','Administrativo','Impostos','Outros'];
const financialTypes=['Receita','Recebimento','Despesa','Pagamento'];
const financialStates=['Previsto','Realizado','Pago','Recebido','Cancelado'];
