const financeIsReal=entry=>['Realizado','Pago','Recebido'].includes(entry.status);
const financeProject=entry=>state.data.projects.find(project=>project.id===entry.projectId);
const financeEntryClient=entry=>entry.clientId||financeProject(entry)?.clientId||'';
