function openFinancialEntry(id=''){const entry=id?state.data.financialEntries.find(item=>item.id===id):null,value=(key,fallback='')=>entry?.[key]??fallback;const selectedClient=value('clientId'),selectedProject=value('projectId'),clientSelect=`<option value="">Sem cliente vinculado</option>${state.data.clients.map(client=>`<option value="${client.id}" ${client.id===selectedClient?'selected':''}>${client.name}</option>`).join('')}`,projectSelect=`<option value="">Sem projeto vinculado</option>${state.data.projects.map(project=>`<option value="${project.id}" ${project.id===selectedProject?'selected':''}>${project.code} · ${project.name}</option>`).join('')}`;$('#dialogTitle').textContent=entry?'Editar lançamento financeiro':'Novo lançamento financeiro';$('#recordForm').dataset.kind='financialEntry';$('#recordForm').dataset.editId=id;$('#saveButton').textContent=entry?'Salvar lançamento':'Registrar lançamento';$('#formFields').innerHTML=`<div class="field"><label>Tipo</label><select name="type">${financialTypes.map(type=>`<option ${type===value('type','Despesa')?'selected':''}>${type}</option>`).join('')}</select></div><div class="field"><label>Situação</label><select name="status">${financialStates.map(status=>`<option ${status===value('status','Realizado')?'selected':''}>${status}</option>`).join('')}</select></div><div class="field"><label>Valor (R$)</label><input name="amount" type="number" min="0" step="0.01" value="${value('amount')}" required></div><div class="field"><label>Data</label><input name="date" type="date" value="${value('date',todayInput())}" required></div><div class="field"><label>Categoria</label><select name="category">${financialCategories.map(category=>`<option ${category===value('category','Materiais')?'selected':''}>${category}</option>`).join('')}</select></div><div class="field"><label>Responsável</label><input name="responsible" value="${value('responsible')}" placeholder="Quem registrou ou executou"></div><div class="field full"><label>Cliente</label><select name="clientId">${clientSelect}</select></div><div class="field full"><label>Projeto</label><select name="projectId">${projectSelect}</select></div><div class="field full"><label>Descrição / comprovante</label><textarea name="description" required placeholder="Ex.: compra de materiais, pagamento de prestador, sinal recebido ou referência do comprovante.">${value('description')}</textarea></div>`;$('#recordDialog').showModal()}
function openFinancialAccount(id=''){const account=id?state.data.financialAccounts.find(item=>item.id===id):null,value=(key,fallback='')=>account?.[key]??fallback;$('#dialogTitle').textContent=account?'Editar conta financeira':'Nova conta financeira';$('#recordForm').dataset.kind='financialAccount';$('#recordForm').dataset.editId=id;$('#saveButton').textContent=account?'Salvar conta':'Cadastrar conta';$('#formFields').innerHTML=`<div class="field full"><label>Nome da conta</label><input name="name" value="${value('name')}" placeholder="Ex.: Conta principal Proelium" required></div><div class="field"><label>Instituição</label><input name="institution" value="${value('institution')}" placeholder="Banco ou carteira"></div><div class="field"><label>Tipo</label><select name="type"><option ${value('type','Corrente')==='Corrente'?'selected':''}>Corrente</option><option ${value('type')==='Poupança'?'selected':''}>Poupança</option><option ${value('type')==='Carteira digital'?'selected':''}>Carteira digital</option></select></div><div class="field"><label>Saldo inicial (R$)</label><input name="initialBalance" type="number" step="0.01" value="${value('initialBalance',0)}"></div><div class="field"><label>Status</label><select name="status"><option ${value('status','Ativa')==='Ativa'?'selected':''}>Ativa</option><option ${value('status')==='Inativa'?'selected':''}>Inativa</option></select></div><div class="field full"><label>Observação</label><textarea name="notes" placeholder="Uso previsto, agência, finalidade ou observações internas.">${value('notes')}</textarea></div>`;$('#recordDialog').showModal()}
function financialAccountsBlock(){const accounts=state.data.financialAccounts,rows=accounts.map(account=>{const linked=state.data.financialEntries.filter(entry=>entry.accountId===account.id),movement=linked.reduce((sum,entry)=>sum+(financeIsIncome(entry)?1:-1)*Number(entry.amount||0),0),balance=Number(account.initialBalance||0)+movement;return `<tr><td><div class="entity">${account.name}</div><div class="subtext">${account.institution||'Instituição não informada'} · ${account.type||'Conta'}</div></td><td><strong>${money(balance)}</strong></td><td>${linked.length}</td><td>${badge(account.status||'Ativa')}</td><td><button class="button secondary" data-financial-account="${account.id}">Editar</button></td></tr>`});return `<section class="card financial-accounts"><div class="card-head"><h3>Contas financeiras</h3><button class="button secondary" data-financial-account>+ Nova conta</button></div>${accounts.length?table(['Conta','Saldo projetado','Lançamentos','Status',''],rows):'<div class="empty">Cadastre a primeira conta para organizar os saldos e futuros vínculos bancários.</div>'}</section>`}
function financialFilterControls(){const filter=state.financialFilters,managers=[...new Set(state.data.projects.map(project=>project.manager).filter(Boolean).concat(state.data.financialEntries.map(financeEntryManager).filter(Boolean)))].sort();return `<div class="module-toolbar financial-filters"><label>De <input type="date" data-finance-filter="from" value="${filter.from}"></label><label>Até <input type="date" data-finance-filter="to" value="${filter.to}"></label><label>Cliente <select data-finance-filter="clientId"><option value="all">Todos</option>${state.data.clients.map(client=>`<option value="${client.id}" ${filter.clientId===client.id?'selected':''}>${client.name}</option>`).join('')}</select></label><label>Responsável <select data-finance-filter="manager"><option value="all">Todos</option>${managers.map(manager=>`<option ${filter.manager===manager?'selected':''}>${manager}</option>`).join('')}</select></label><label>Categoria <select data-finance-filter="category"><option value="all">Todas</option>${financialCategories.map(category=>`<option ${filter.category===category?'selected':''}>${category}</option>`).join('')}</select></label><button class="button secondary" data-finance-clear>Limpar filtros</button></div>`}
function financeBlock7(){const projects=filteredFinancialProjects(),entries=filteredFinancialEntries().filter(entry=>entry.status!=='Cancelado'),plannedRevenue=projects.reduce((sum,project)=>sum+Number(project.budget||0),0),plannedCost=projects.reduce((sum,project)=>sum+Number(project.cost||0),0),actualRevenue=entries.filter(entry=>financeIsIncome(entry)&&financeIsReal(entry)).reduce((sum,entry=>sum+Number(entry.amount||0)),0),actualCost=entries.filter(entry=>!financeIsIncome(entry)&&financeIsReal(entry)).reduce((sum,entry=>sum+Number(entry.amount||0)),0),rows=projects.map(project=>{const metric=financialProjectMetrics(project);return `<tr><td><div class="entity">${project.name}</div><div class="subtext">${clientName(project.clientId)} · ${project.manager||'—'}</div></td><td>${money(metric.forecastRevenue)}</td><td>${money(metric.forecastCost)}</td><td>${money(metric.actualRevenue)}</td><td>${money(metric.actualCost)}</td><td>${money(metric.actualRevenue-metric.actualCost)}</td><td>${metric.forecastMargin}%</td></tr>`});return heading('Financeiro','Planejado, realizado e resultado por cliente e projeto.')+`<div class="module-toolbar"><button class="button primary" data-financial-entry>+ Novo lançamento</button><span class="subtext">Registre receitas, despesas, pagamentos e recebimentos para alimentar o BI.</span></div>`+financialFilterControls()+`<div class="kpi-grid"><div class="kpi"><div class="kpi-top">Receita prevista</div><div class="kpi-value">${money(plannedRevenue)}</div><div class="kpi-note">orçamentos aprovados nos projetos filtrados</div></div><div class="kpi"><div class="kpi-top">Custo previsto</div><div class="kpi-value">${money(plannedCost)}</div><div class="kpi-note">estimativa de materiais e serviços</div></div><div class="kpi"><div class="kpi-top">Receita realizada</div><div class="kpi-value">${money(actualRevenue)}</div><div class="kpi-note">recebimentos e receitas registrados</div></div><div class="kpi"><div class="kpi-top">Custo realizado</div><div class="kpi-value">${money(actualCost)}</div><div class="kpi-note">despesas e pagamentos realizados</div></div></div>`+`<section class="card commercial-history"><div class="card-head"><h3>Previsto × realizado por projeto</h3><span class="subtext">Resultado realizado só aparece após lançamento financeiro.</span></div>${table(['Projeto / cliente','Receita prev.','Custo prev.','Receita real','Custo real','Resultado real','Margem prev.'],rows)}</section><section class="card commercial-history"><div class="card-head"><h3>Lançamentos financeiros</h3><span class="subtext">${entries.length} registro(s) no filtro atual</span></div>${table(['Data','Tipo','Descrição','Cliente / projeto','Categoria','Valor','Situação',''],entries.sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(entry=>`<tr><td>${entry.date?new Date(entry.date+'T12:00:00').toLocaleDateString('pt-BR'):'—'}</td><td>${badge(entry.type)}</td><td><div class="entity">${entry.description}</div><div class="subtext">${financeEntryManager(entry)||'Sem responsável'}</div></td><td>${clientName(financeEntryClient(entry))}<div class="subtext">${entry.projectId?projectName(entry.projectId):'Sem projeto'}</div></td><td>${entry.category}</td><td><strong>${money(Number(entry.amount||0))}</strong></td><td>${badge(entry.status)}</td><td><button class="button secondary" data-financial-entry="${entry.id}">Editar</button></td></tr>`))}</section>`}
function biBlock7(){const projects=filteredFinancialProjects(),entries=filteredFinancialEntries(),quotes=state.data.quotes.filter(quote=>(state.financialFilters.clientId==='all'||quote.clientId===state.financialFilters.clientId)),approvedQuotes=quotes.filter(quote=>quote.status==='Aprovado'),approvalRate=quotes.length?Math.round(approvedQuotes.length/quotes.length*100):0,openProjects=projects.filter(project=>!['Concluído','Cancelado'].includes(project.status)),lateTasks=state.data.tasks.filter(task=>task.due==='Atrasada'&&projects.some(project=>project.id===task.projectId)).length,productSales={};state.data.quoteRooms.filter(room=>approvedQuotes.some(quote=>quote.id===room.quoteId)).forEach(room=>(room.items||[]).forEach(item=>{const product=productById(item.productId);if(!product)return;const record=productSales[product.id]??={name:product.name,category:product.category,qty:0,value:0,cost:0};record.qty+=Number(item.qty||0);record.value+=Number(product.price||0)*Number(item.qty||0)*(1-Number(item.discount||0)/100);record.cost+=Number(product.cost||0)*Number(item.qty||0)}));const bestProducts=Object.values(productSales).filter(item=>state.financialFilters.category==='all'||item.category===state.financialFilters.category).sort((a,b)=>b.value-a.value),rooms=state.data.quoteRooms.filter(room=>approvedQuotes.some(quote=>quote.id===room.quoteId)).map(room=>{const values=quoteRoomTotals(room);return {name:room.name,client:clientName(state.data.quotes.find(quote=>quote.id===room.quoteId)?.clientId),cost:values.cost,price:values.price,margin:quoteMargin(values)}}).sort((a,b)=>b.price-a.price),actualCost=entries.filter(entry=>!financeIsIncome(entry)&&financeIsReal(entry)).reduce((sum,entry=>sum+Number(entry.amount||0)),0),actualRevenue=entries.filter(entry=>financeIsIncome(entry)&&financeIsReal(entry)).reduce((sum,entry=>sum+Number(entry.amount||0)),0);return heading('Business Intelligence','Painel de decisão alimentado por comercial, projetos, operação e financeiro.')+financialFilterControls()+`<div class="kpi-grid"><div class="kpi"><div class="kpi-top">Taxa de aprovação</div><div class="kpi-value">${approvalRate}%</div><div class="kpi-note">${approvedQuotes.length}/${quotes.length} orçamentos no filtro</div></div><div class="kpi"><div class="kpi-top">Projetos em andamento</div><div class="kpi-value">${openProjects.length}</div><div class="kpi-note">${lateTasks} pendência(s) marcada(s) em atraso</div></div><div class="kpi"><div class="kpi-top">Resultado realizado</div><div class="kpi-value">${money(actualRevenue-actualCost)}</div><div class="kpi-note">receita menos custo registrado</div></div><div class="kpi"><div class="kpi-top">Margem prevista</div><div class="kpi-value">${projects.reduce((sum,project)=>sum+Number(project.budget||0),0)?Math.round((projects.reduce((sum,project)=>sum+Number(project.budget||0),0)-projects.reduce((sum,project)=>sum+Number(project.cost||0),0))/projects.reduce((sum,project)=>sum+Number(project.budget||0),0)*100):0}%</div><div class="kpi-note">base dos projetos filtrados</div></div></div>`+`<div class="dashboard-grid"><section class="card"><div class="card-head"><h3>Produtos e serviços mais vendidos</h3><span class="subtext">somente orçamentos aprovados</span></div>${bestProducts.length?`<div class="bi-bars">${bestProducts.slice(0,8).map(item=>`<div class="bi-bar-row"><div><strong>${item.name}</strong><small>${item.qty} unidade(s) · ${item.category}</small></div><div class="bi-track"><span style="width:${Math.max(8,item.value/Math.max(...bestProducts.map(row=>row.value))*100)}%"></span></div><b>${money(item.value)}</b></div>`).join('')}</div>`:'<div class="empty">Aprove orçamentos com itens para gerar este ranking.</div>'}</section><section class="card"><div class="card-head"><h3>Margem por cômodo</h3><span class="subtext">dos orçamentos aprovados</span></div>${rooms.length?`<div class="bi-breakdown">${rooms.slice(0,8).map(room=>`<div><div><strong>${room.name}</strong><small>${room.client} · ${money(room.price)}</small></div><span>${room.margin}% margem</span></div>`).join('')}</div>`:'<div class="empty">Ainda não há ambientes em propostas aprovadas.</div>'}</section></div><section class="card bi-table"><div class="card-head"><h3>Comparação por cliente e projeto</h3><span class="subtext">Filtros aplicados a responsável e cliente.</span></div>${table(['Cliente','Projeto','Etapa','Orçado','Custo previsto','Custo real','Execução','Atrasos'],projects.map(project=>{const metrics=financialProjectMetrics(project),late=state.data.tasks.filter(task=>task.projectId===project.id&&task.due==='Atrasada').length;return `<tr><td>${clientName(project.clientId)}</td><td>${project.name}</td><td>${badge(project.technicalStage||'Projeto técnico')}</td><td>${money(metrics.forecastRevenue)}</td><td>${money(metrics.forecastCost)}</td><td>${money(metrics.actualCost)}</td><td>${project.progress||0}%</td><td>${late?badge(`${late} pendência(s)`):'—'}</td></tr>`}))}</section>`}
const block7SaveRecord=saveRecord;saveRecord=(kind,data,editId='')=>{if(kind==='financialEntry'){const entry={type:data.type,status:data.status,amount:Number(data.amount||0),date:data.date,category:data.category,responsible:data.responsible,clientId:data.clientId,projectId:data.projectId,description:data.description};if(editId){const index=state.data.financialEntries.findIndex(item=>item.id===editId);if(index>=0)state.data.financialEntries[index]={...state.data.financialEntries[index],...entry}}else state.data.financialEntries.unshift({id:uid('fin'),createdAt:new Date().toISOString(),...entry});persist();render();toast(editId?'Lançamento financeiro atualizado.':'Lançamento registrado e refletido no BI.');return}return block7SaveRecord(kind,data,editId)};
const accountSaveRecord=saveRecord;saveRecord=(kind,data,editId='')=>{if(kind==='financialAccount'){const account={name:String(data.name||'').trim(),institution:String(data.institution||'').trim(),type:data.type,status:data.status,initialBalance:Number(data.initialBalance||0),notes:String(data.notes||'').trim()};if(!account.name){toast('Informe o nome da conta.');return}if(editId){const index=state.data.financialAccounts.findIndex(item=>item.id===editId);if(index>=0)state.data.financialAccounts[index]={...state.data.financialAccounts[index],...account}}else state.data.financialAccounts.unshift({id:uid('acc'),createdAt:new Date().toISOString(),...account});persist();render();toast(editId?'Conta financeira atualizada.':'Conta financeira cadastrada.');return}return accountSaveRecord(kind,data,editId)};
