// Integração operacional: a OS torna-se o elo entre comercial, projeto, campo e entrega.
function operationalOrderContext(order){
  const project=state.data.projects.find(item=>item.id===order.projectId);
  const quote=project?.quoteId?state.data.quotes.find(item=>item.id===project.quoteId):null;
  const checklist=project?checklistForProject(project.id):[];
  const reports=(state.data.serviceReports||[]).filter(item=>item.serviceOrderId===order.id);
  const delivery=project?(state.data.projectDeliveries||[]).find(item=>item.projectId===project.id):null;
  const asset=order.equipmentId?state.data.equipment.find(item=>item.id===order.equipmentId):null;
  return {project,quote,checklist,reports,delivery,asset};
}
function openOrderServiceReport(orderId){
  const order=state.data.serviceOrders.find(item=>item.id===orderId),project=order&&state.data.projects.find(item=>item.id===order.projectId);
  if(!order||!project){toast('Vincule esta OS a um projeto antes de registrar o relatório técnico.');return}
  $('#dialogTitle').textContent=`Relatório da ${order.code}`;
  $('#recordForm').dataset.kind='serviceOrderReport';$('#recordForm').dataset.editId='';$('#saveButton').textContent='Salvar relatório da OS';
  $('#formFields').innerHTML=`<input type="hidden" name="serviceOrderId" value="${order.id}"><input type="hidden" name="projectId" value="${project.id}"><div class="field full"><label>OS vinculada</label><input value="${order.code} · ${order.type}" disabled></div><div class="field full"><label>Projeto</label><input value="${project.name}" disabled></div><div class="field"><label>Data do serviço</label><input name="date" type="date" value="${order.date||todayInput()}" required></div><div class="field"><label>Responsável técnico</label><input name="technician" value="${order.assignee||project.manager||''}" required></div><div class="field full"><label>Serviço executado, testes e pendências</label><textarea name="execution" required placeholder="Registre o que foi realizado, testes, materiais e próximas ações."></textarea></div><div class="field"><label>Situação</label><select name="status"><option>Concluído</option><option>Parcial</option><option>Pendente</option></select></div><div class="field"><label>Fotos / arquivos</label><input name="media" type="text" placeholder="Referência, link ou nome do arquivo"></div>`;
  $('#recordDialog').showModal();
}
function serviceOrderDetail(){
  const order=state.data.serviceOrders.find(item=>item.id===state.selectedServiceOrder);
  if(!order){state.view='operations';return operationsBlock6()}
  const {project,quote,checklist,reports,delivery,asset}=operationalOrderContext(order),checked=checklist.filter(item=>item.done).length;
  const linkState=project?'Projeto vinculado':'Projeto não vinculado';
  return `<button class="back-link" data-service-order-back>← Voltar para operação</button><div class="client-hero card"><div><p class="eyebrow">ORDEM DE SERVIÇO</p><h2>${order.code}</h2><p>${order.type} · ${clientName(order.clientId)} · ${badge(order.status)}</p></div><div class="hero-actions"><button class="button secondary" data-operational-order="${order.id}">Editar OS</button><button class="button primary" data-order-report="${order.id}">+ Relatório de serviço</button></div></div><div class="client-summary"><div class="card info-card"><span>Agenda</span><strong>${order.date?new Date(order.date+'T12:00:00').toLocaleDateString('pt-BR'):'Sem data'}</strong><p>${order.time||'Sem horário'} · ${order.assignee||'Responsável a definir'}</p></div><div class="card info-card"><span>Projeto</span><strong>${project?.name||'Não vinculado'}</strong><p>${project?`${project.technicalStage} · ${project.progress||0}%`:'Edite a OS e selecione o projeto.'}</p></div><div class="card info-card"><span>Checklist</span><strong>${checked}/${checklist.length}</strong><p>${project?'verificações do projeto':'aguarda vínculo técnico'}</p></div><div class="card info-card"><span>Entrega</span><strong>${delivery?.acceptance||'Não registrada'}</strong><p>${delivery?.date||'Aguardando conclusão'}</p></div></div><section class="card operational-section"><div class="card-head"><h3>Rastreabilidade da OS</h3><span class="subtext">comercial → projeto → campo → entrega</span></div><div class="technical-mini-list"><article><strong>Comercial</strong><small>${quote?`${quote.title} · ${badge(quote.status)}`:'Orçamento será mostrado quando o projeto vier de uma proposta aprovada.'}</small></article><article><strong>Área técnica / projeto</strong><small>${project?`${project.code} · ${project.technicalStage} · ${linkState}`:linkState}</small>${project?`<button class="link-button" data-order-project="${project.id}">Abrir projeto e checklist →</button>`:''}</article><article><strong>Ativo e instalação</strong><small>${asset?`${equipmentLabel(asset)} · ${asset.location||'local não informado'} · série ${asset.serial||'não informada'}`:'Nenhum equipamento específico vinculado a esta OS.'}</small></article><article><strong>Escopo da ordem</strong><small>${order.description||'Sem descrição'}</small></article></div></section><div class="project-execution-grid"><section class="card"><div class="card-head"><h3>Checklist vinculado</h3>${project?`<button data-order-project="${project.id}">Abrir checklist →</button>`:''}</div><div class="project-checklist">${checklist.map(item=>`<div class="check-row ${item.done?'completed':''}"><span>${item.done?'✓':'○'}</span><span>${item.title}<small>${item.phase}</small></span></div>`).join('')||'<div class="empty">Esta OS ainda não está vinculada a um projeto com checklist.</div>'}</div></section><section class="card service-report-list"><div class="card-head"><h3>Relatórios desta OS</h3><button data-order-report="${order.id}">+ Registrar</button></div>${reports.map(report=>`<article><div><span class="agenda-type">${report.status}</span><strong>${report.date?new Date(report.date+'T12:00:00').toLocaleDateString('pt-BR'):'Sem data'} · ${report.technician}</strong><p>${report.execution}</p>${report.media?`<small>Arquivo/foto: ${report.media}</small>`:''}</div></article>`).join('')||'<div class="empty">Nenhum relatório registrado para esta OS.</div>'}</section></div>${project?`<section class="card project-linked-installation"><div class="card-head"><h3>Entrega e aceite</h3>${!delivery?`<button data-order-delivery="${project.id}">Registrar entrega →</button>`:''}</div><p>${delivery?`${delivery.acceptance} · ${delivery.note}`:'A entrega fica disponível após a conclusão do checklist do projeto.'}</p></section>`:''}`
}
const block6IntegratedOperations=operationsBlock6;operationsBlock6=()=>block6IntegratedOperations().replaceAll('data-operational-order="','data-open-service-order="');
const block6IntegrationSave=saveRecord;saveRecord=(kind,data,editId='')=>{if(kind==='serviceOrderReport'){if(!Array.isArray(state.data.serviceReports))state.data.serviceReports=[];const order=state.data.serviceOrders.find(item=>item.id===data.serviceOrderId);if(!order)return;state.data.serviceReports.unshift({id:uid('rpt'),projectId:data.projectId,serviceOrderId:data.serviceOrderId,date:data.date,technician:data.technician,execution:data.execution,status:data.status,media:data.media||''});if(data.status==='Concluído'&&order.status!=='Cancelada')order.status='Concluída';persist();render();toast('Relatório vinculado à OS, ao projeto e ao histórico técnico.');return}return block6IntegrationSave(kind,data,editId)};
