document.addEventListener('click',event=>{const open=event.target.closest('[data-open-service-order]'),back=event.target.closest('[data-service-order-back]'),report=event.target.closest('[data-order-report]'),project=event.target.closest('[data-order-project]'),delivery=event.target.closest('[data-order-delivery]');if(open){state.selectedServiceOrder=open.dataset.openServiceOrder;state.view='serviceOrderDetail';render()}if(back){state.view='operations';render()}if(report)openOrderServiceReport(report.dataset.orderReport);if(project){state.selectedProject=project.dataset.orderProject;state.view='projectDetail';render()}if(delivery)openProjectDelivery(delivery.dataset.orderDelivery)});
