// Ativação final do BI após todos os módulos de comercial e operação.
function financialSum(entries,predicate){let total=0;entries.forEach(entry=>{if(predicate(entry))total+=Number(entry.amount||0)});return total}
function financeBlock7Safe(){const projects=filteredFinancialProjects(),entries=filteredFinancialEntries().filter(entry=>entry.status!=='Cancelado'),forecastRevenue=projects.reduce((total,project)=>total+Number(project.budget||0),0),forecastCost=projects.reduce((total,project)=>total+Number(project.cost||0),0),actualRevenue=financialSum(entries,entry=>financeIsIncome(entry)&&financeIsReal(entry)),actualCost=financialSum(entries,entry=>!financeIsIncome(entry)&&financeIsReal(entry)),rows=projects.map(project=>{const projectEntries=entries.filter(entry=>entry.projectId===project.id),revenue=financialSum(projectEntries,entry=>financeIsIncome(entry)&&financeIsReal(entry)),cost=financialSum(projectEntries,entry=>!financeIsIncome(entry)&&financeIsReal(entry)),margin=project.budget?Math.round((Number(project.budget)-Number(project.cost||0))/Number(project.budget)*100):0;return `<tr><td><div class="entity">${project.name}</div><div class="subtext">${clientName(project.clientId)} · ${project.manager||'—'}</div></td><td>${money(project.budget||0)}</td><td>${money(project.cost||0)}</td><td>${money(revenue)}</td><td>${money(cost)}</td><td>${money(revenue-cost)}</td><td>${margin}%</td></tr>`});return heading('Financeiro','Planejado, realizado e resultado por cliente e projeto.')+`<div class="module-toolbar"><button class="button primary" data-financial-entry>+ Novo lançamento</button><span class="subtext">Registre receitas, despesas, pagamentos e recebimentos para alimentar o BI.</span></div>`+financialFilterControls()+`<div class="kpi-grid"><div class="kpi"><div class="kpi-top">Receita prevista</div><div class="kpi-value">${money(forecastRevenue)}</div><div class="kpi-note">orçamentos aprovados nos projetos filtrados</div></div><div class="kpi"><div class="kpi-top">Custo previsto</div><div class="kpi-value">${money(forecastCost)}</div><div class="kpi-note">estimativa de materiais e serviços</div></div><div class="kpi"><div class="kpi-top">Receita realizada</div><div class="kpi-value">${money(actualRevenue)}</div><div class="kpi-note">recebimentos e receitas registrados</div></div><div class="kpi"><div class="kpi-top">Custo realizado</div><div class="kpi-value">${money(actualCost)}</div><div class="kpi-note">despesas e pagamentos realizados</div></div></div><section class="card commercial-history"><div class="card-head"><h3>Previsto × realizado por projeto</h3><span class="subtext">Resultado realizado só aparece após lançamento financeiro.</span></div>${table(['Projeto / cliente','Receita prev.','Custo prev.','Receita real','Custo real','Resultado real','Margem prev.'],rows)}</section><section class="card commercial-history"><div class="card-head"><h3>Lançamentos financeiros</h3><span class="subtext">${entries.length} registro(s) no filtro atual</span></div>${table(['Data','Tipo','Descrição','Cliente / projeto','Categoria','Valor','Situação',''],entries.sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(entry=>`<tr><td>${entry.date?new Date(entry.date+'T12:00:00').toLocaleDateString('pt-BR'):'—'}</td><td>${badge(entry.type)}</td><td><div class="entity">${entry.description}</div><div class="subtext">${financeEntryManager(entry)||'Sem responsável'}</div></td><td>${clientName(financeEntryClient(entry))}<div class="subtext">${entry.projectId?projectName(entry.projectId):'Sem projeto'}</div></td><td>${entry.category}</td><td><strong>${money(entry.amount||0)}</strong></td><td>${badge(entry.status)}</td><td><button class="button secondary" data-financial-entry="${entry.id}">Editar</button></td></tr>`))}</section>`}
