// BI de desempenho: cada obra ganha uma curva de leitura e uma análise ao ser selecionada.
function performanceData(project){const entries=(state.data.financialEntries||[]).filter(entry=>entry.projectId===project.id&&entry.status!=='Cancelado'),costReal=financialSum(entries.filter(entry=>!financeIsIncome(entry)&&financeIsReal(entry)),entry=>true),overdue=(state.data.tasks||[]).filter(task=>task.projectId===project.id&&task.due==='Atrasada').length,margin=project.budget?Math.round((Number(project.budget)-Number(project.cost||0))/Number(project.budget)*100):0,score=Math.max(0,Math.min(100,Math.round(margin*.55+Number(project.progress||0)*.45-overdue*7))),target={'Projeto técnico':20,'Cabeamento':48,'Instalação':78,'Entrega':100,'Concluído':100}[project.technicalStage]||50,costPercent=project.cost&&costReal?Math.round(costReal/Number(project.cost)*100):null,start=Math.max(9,Math.round(Number(project.progress||0)*.18)),line=[start,Math.max(start+4,Math.round(Number(project.progress||0)*.42)),Math.max(start+8,Math.round(Number(project.progress||0)*.68)-overdue*5),Math.max(0,Number(project.progress||0)-overdue*7),Math.max(0,Math.min(100,Number(project.progress||0)+(100-target)*.12-overdue*5))],signal=overdue||costPercent>100?'Atenção':score>=68?'Em destaque':'Em acompanhamento';return {...project,margin,score,costReal,costPercent,overdue,target,line,signal}}
