// Time operacional no BI: liderança e execução são lidas pela mesma base de evidências.
function performanceTeamPanel(){const records=state.data.evaluations||[],tasks=state.data.tasks||[],orders=state.data.serviceOrders||[],projects=state.data.projects||[],namesFor=person=>person.name==='Colaborador técnico'?['Colaborador técnico','Colaborador técnico','Colaborador']:[person.name],rows=(state.data.collaborators||[]).filter(person=>person.status!=='Inativo').map(person=>{const names=namesFor(person),evaluations=records.filter(record=>names.includes(record.collaborator)||names.includes(record.evaluator)),assignedTasks=tasks.filter(task=>names.includes(task.assignee)),assignedOrders=orders.filter(order=>names.includes(order.assignee)),managedProjects=projects.filter(project=>names.includes(project.manager)),quality=evaluations.length?evaluations.reduce((sum,record)=>sum+(Number(record.installation||0)+Number(record.service||0)+Number(record.commitment||0)+Number(record.deadline||0))/4,0)/evaluations.length:0,evidence=evaluations.length+assignedTasks.length+assignedOrders.length+managedProjects.length,score=evidence?Math.round(Math.min(100,quality*14+Math.min(30,evidence*5))):null;return {...person,evaluations,assignedTasks,assignedOrders,managedProjects,quality,evidence,score}}).sort((a,b)=>(b.score??-1)-(a.score??-1)||b.evidence-a.evidence),card=row=>`<article><span class="team-rank">${row.score===null?'—':row.score}</span><div class="collaborator-avatar">${row.name.split(' ').map(name=>name[0]).slice(0,2).join('')}</div><div><strong>${row.name}</strong><small>${row.role||'Colaborador'}</small></div><b>${row.quality?row.quality.toFixed(1):'—'}</b><div class="team-bars"><i title="Qualidade" style="width:${row.quality?row.quality*20:0}%"></i><i title="Tarefas" style="width:${Math.min(100,row.assignedTasks.length*25)}%"></i><i title="OS" style="width:${Math.min(100,row.assignedOrders.length*35)}%"></i><i title="Projetos" style="width:${Math.min(100,row.managedProjects.length*35)}%"></i></div><em>${row.evidence?`${row.evaluations.length} avaliação(ões) · ${row.assignedTasks.length} tarefa(s) · ${row.assignedOrders.length} OS · ${row.managedProjects.length} projeto(s)`:'Aguardando registros'}</em></article>`;return `<section class="team-performance card bi-performance-team"><div class="card-head"><div><h3>Time operacional e liderança</h3><p class="subtext">Inclui direção, gestão e operação. A pontuação combina avaliações e registros vinculados; sem evidência, não há nota inventada.</p></div><span class="subtext">nota de qualidade · índice de evidências</span></div><div class="team-performance-grid">${rows.map(card).join('')||'<p class="subtext">Cadastre colaboradores para acompanhar a equipe.</p>'}</div></section>`}
const biDesempenhoWithTeam=views.biMarket;
views.biMarket=()=>biDesempenhoWithTeam()+performanceTeamPanel();

const biPerformanceWithTickerFinal=views.biMarket;
views.biMarket=()=>biPerformanceWithTickerFinal().replace('</header><div class="performance-summary">',`</header>${performanceTicker()}<div class="performance-summary">`).replace('<section class="performance-project-grid">',`${performanceAnalytics()}<section class="performance-project-grid">`);

// Faixa de cotações: transforma as obras em ativos acompanháveis sem criar
// dados artificiais. A variação é a distância entre execução e etapa esperada.
function performanceTicker(){const projects=(state.data.projects||[]).map(performanceData).sort((a,b)=>b.score-a.score),items=projects.slice(0,8).map(project=>{const delta=Math.round(Number(project.progress||0)-Number(project.target||0));return `<span class="performance-ticker-item"><b>${project.code||project.id.slice(-4).toUpperCase()}</b><small>${project.name}</small><em class="${delta>=0?'up':'down'}">${delta>=0?'+':''}${delta} pts</em></span>`}).join('');return `<div class="performance-ticker"><span class="performance-ticker-label"><i></i>ATIVOS EM MOVIMENTO</span>${items||'<span class="performance-ticker-empty">Cadastre projetos para formar a carteira.</span>'}</div>`}
function performanceAnalytics(){const projects=(state.data.projects||[]).map(performanceData),selected=projects.find(project=>project.id===state.biMarketAsset),rows=(selected?[selected]:projects).slice(0,8),max=Math.max(1,...rows.map(project=>Number(project.budget||0))),line=rows.map((project,index)=>`${index*44+8},${105-Math.max(8,Math.min(92,project.score))}`).join(' '),bars=rows.map(project=>{const width=Math.max(6,Math.round(Number(project.budget||0)/max*100));return `<div><span>${project.code||project.id.slice(-4).toUpperCase()}</span><i><b style="width:${width}%"></b></i><em>${money(project.budget||0)}</em></div>`}).join('');return `<section class="performance-analytics"><article class="analytics-chart"><header><div><small>${selected?'ATIVO SELECIONADO':'CARTEIRA'}</small><strong>${selected?'Trajetória da obra':'Índice de performance das obras'}</strong></div><em>${selected?`${selected.score}/100`:`${projects.length} ativos`}</em></header><svg viewBox="0 0 320 120" role="img" aria-label="Gráfico de performance das obras"><path d="M8 105H312M8 58H312M8 12H312"/><polyline points="${line||'8,105 312,105'}"/>${selected?`<circle cx="8" cy="${105-Math.max(8,Math.min(92,selected.score))}" r="4"/>`:''}</svg><footer><span>início</span><span>execução</span><span>previsão</span></footer></article><article class="analytics-chart analytics-bars"><header><div><small>CAPITAL DA CARTEIRA</small><strong>Volume por obra</strong></div><em>${money(rows.reduce((sum,project)=>sum+Number(project.budget||0),0))}</em></header><div class="analytics-bar-list">${bars||'<p>Nenhum projeto cadastrado.</p>'}</div></article></section>`}
const biPerformanceWithTicker=views.biMarket;
views.biMarket=()=>biPerformanceWithTicker().replace('</header><div class="performance-summary">',`</header>${performanceTicker()}<div class="performance-summary">`);
render();

