// Acompanhamento é uma visão única do projeto, não depende de uma instalação criada manualmente.
function unifiedFollowUp(){const projects=state.data.projects.filter(project=>matches(project.name,clientName(project.clientId),project.manager,project.technicalStage,project.status)),open=projects.filter(project=>!['Concluído','Cancelado'].includes(project.status)),rows=projects.map(project=>{const installation=state.data.installations.find(item=>item.projectId===project.id),tasks=state.data.tasks.filter(item=>item.projectId===project.id),pending=tasks.filter(item=>item.status!=='Concluída').length,late=tasks.filter(item=>item.due==='Atrasada').length,orders=(state.data.serviceOrders||[]).filter(item=>item.projectId===project.id),reports=(state.data.serviceReports||[]).filter(item=>item.projectId===project.id),appointment=state.data.appointments.filter(item=>item.projectId===project.id).sort((a,b)=>String(a.date).localeCompare(String(b.date)))[0];return `<tr><td><div class="entity">${project.name}</div><div class="subtext">${project.code||'Sem código'} · ${clientName(project.clientId)}</div></td><td>${project.manager||'A definir'}</td><td>${badge(project.technicalStage||'Projeto técnico')}</td><td><strong>${project.progress||0}%</strong><div class="progress"><span style="width:${project.progress||0}%"></span></div></td><td>${appointment?`${appointment.date||'Sem data'} · ${appointment.title}`:'Sem compromisso agendado'}</td><td>${pending?`${pending} pendência(s)${late?` · ${late} atraso(s)`:''}`:'Em dia'}<div class="subtext">${orders.length} OS · ${reports.length} relatório(s)</div></td><td>${installation?badge(installation.status||'Instalação vinculada'):'Acompanhar pelo projeto'}</td><td><button class="button secondary" data-open-project="${project.id}">Abrir</button></td></tr>`}).join('');return heading('Acompanhamento','Visão integrada: cliente, projeto, agenda, tarefas, OS, relatórios e instalação no mesmo fluxo.','installation')+`<div class="module-toolbar"><button class="button secondary" data-add="installation">+ Vincular instalação</button><button class="button secondary" data-view="operations">Abrir operação</button></div><div class="kpi-grid"><div class="kpi"><div class="kpi-top">Projetos acompanhados</div><div class="kpi-value">${projects.length}</div><div class="kpi-note">todos os projetos vinculados a clientes</div></div><div class="kpi"><div class="kpi-top">Em execução</div><div class="kpi-value">${open.filter(project=>project.status==='Em execução').length}</div><div class="kpi-note">obras ativas</div></div><div class="kpi"><div class="kpi-top">OS vinculadas</div><div class="kpi-value">${(state.data.serviceOrders||[]).filter(order=>projects.some(project=>project.id===order.projectId)).length}</div><div class="kpi-note">agenda operacional integrada</div></div><div class="kpi"><div class="kpi-top">Relatórios de campo</div><div class="kpi-value">${(state.data.serviceReports||[]).filter(report=>projects.some(project=>project.id===report.projectId)).length}</div><div class="kpi-note">histórico técnico disponível</div></div></div><section class="card"><div class="card-head"><div><h3>Fluxo de acompanhamento</h3><p class="subtext">Abra um projeto para atualizar checklist, tarefas, relatórios e a entrega. A instalação é um complemento técnico deste mesmo projeto.</p></div></div>${table(['Projeto / cliente','Responsável','Etapa','Progresso','Próxima agenda','Execução','Instalação',''],rows)}</section>`}
views.installations=unifiedFollowUp;
render();

function unifiedFollowUpSafe(){['projects','installations','tasks','appointments','serviceOrders','serviceReports','equipment'].forEach(key=>{if(!Array.isArray(state.data[key]))state.data[key]=[]});try{return unifiedFollowUp()}catch(error){console.error('Falha ao abrir acompanhamento',error);return heading('Acompanhamento','A base está sendo atualizada. Abra Projetos enquanto a sincronização termina.','installation')+`<section class="card empty"><p>Não foi possível montar a leitura integrada agora.</p><button class="button primary" data-view="projects">Abrir projetos</button></section>`}}
