function operationsDetailed(){const orders=state.data.serviceOrders||[],tickets=state.data.supportTickets||[],types=['Visita técnica','Instalação','Manutenção','Chamado','Troca','Retirada'],typeSummary=types.filter(type=>orders.some(order=>order.type===type)).map(type=>`<div class="kpi"><div class="kpi-top">${type}</div><div class="kpi-value">${orders.filter(order=>order.type===type).length}</div><div class="kpi-note">ordem(ns) registrada(s)</div></div>`).join(''),rows=orders.map(order=>{const project=state.data.projects.find(item=>item.id===order.projectId),asset=order.equipmentId?state.data.equipment.find(item=>item.id===order.equipmentId):null,reports=(state.data.serviceReports||[]).filter(report=>report.serviceOrderId===order.id);return `<tr><td><div class="entity">${order.code}</div><div class="subtext">${order.date?new Date(order.date+'T12:00:00').toLocaleDateString('pt-BR'):'Sem data'}${order.time?` · ${order.time}`:''}</div></td><td>${badge(order.type||'Atendimento')}</td><td><div class="entity">${order.description||'Escopo não informado'}</div><div class="subtext">${asset?`${equipmentLabel(asset)} · ${asset.location||'local não informado'}`:'Sem ativo específico'}</div></td><td>${clientName(order.clientId)}<div class="subtext">${project?`${project.code||'Projeto'} · ${project.name}`:'Sem projeto vinculado'}</div></td><td>${order.assignee||'A definir'}<div class="subtext">${reports.length} relatório(s) de campo</div></td><td>${badge(order.status||'Agendada')}</td><td><button class="button secondary" data-open-service-order="${order.id}">Detalhes</button></td></tr>`}).join('');return heading('Operação e pós-venda','Planeje e acompanhe cada atendimento por tipo de serviço, escopo e histórico técnico.','operations')+`<div class="module-toolbar"><button class="button primary" data-operational-order>+ Nova ordem de serviço</button><button class="button secondary" data-operational-ticket>+ Novo chamado</button></div><section class="card operational-section"><div class="card-head"><div><h3>Tipos de atendimento</h3><p class="subtext">Use Manutenção para pós-venda, Chamado para ocorrência e Troca/Retirada para movimentação de equipamento.</p></div></div><div class="kpi-grid">${typeSummary||'<div class="empty">Crie a primeira ordem de serviço para classificar o atendimento.</div>'}</div></section><section class="card operational-section"><div class="card-head"><div><h3>Ordens de serviço em detalhe</h3><p class="subtext">Todas vinculadas à agenda; abra para consultar checklist, relatórios e entrega.</p></div></div>${orders.length?table(['OS / agenda','Tipo de serviço','Escopo e equipamento','Cliente / projeto','Equipe e relatório','Situação',''],rows):'<div class="empty">Ainda não há ordens de serviço.</div>'}</section><section class="card operational-section"><div class="card-head"><h3>Chamados e manutenções</h3><span class="subtext">${tickets.filter(ticket=>!['Resolvido','Cancelado'].includes(ticket.status)).length} em aberto</span></div>${tickets.length?table(['Tipo','Cliente','Descrição','Prioridade','Situação',''],tickets.map(ticket=>`<tr><td>${badge(ticket.type||'Chamado')}</td><td>${clientName(ticket.clientId)}</td><td>${ticket.description||'—'}</td><td>${badge(ticket.priority||'Média')}</td><td>${badge(ticket.status||'Aberto')}</td><td><button class="button secondary" data-operational-ticket="${ticket.id}">Abrir</button></td></tr>`)):'<div class="empty">Nenhum chamado registrado.</div>'}</section>`}
