if(!Array.isArray(state.data.executionEntries))state.data.executionEntries=[];
const executionKinds=['Mão de obra','Material de execução','Transporte e logística','Serviço terceirizado','Outros gastos'];
const executionFinanceCategory=kind=>({'Mão de obra':'Mão de obra','Material de execução':'Materiais','Transporte e logística':'Logística','Serviço terceirizado':'Serviços terceirizados','Outros gastos':'Outros'})[kind]||'Outros';
function executionMetrics(projectId){const entries=(state.data.executionEntries||[]).filter(entry=>entry.projectId===projectId);return {entries,total:entries.reduce((sum,entry)=>sum+Number(entry.amount||0),0),labor:entries.filter(entry=>entry.kind==='Mão de obra').reduce((sum,entry)=>sum+Number(entry.amount||0),0)}}
function openExecutionEntry(id=''){const entry=id?state.data.executionEntries.find(item=>item.id===id):null,value=(key,fallback='')=>entry?.[key]??fallback;$('#dialogTitle').textContent=entry?'Editar lançamento de execução':'Novo gasto de execução';$('#recordForm').dataset.kind='executionEntry';$('#recordForm').dataset.editId=id;$('#saveButton').textContent=entry?'Salvar lançamento':'Registrar gasto';$('#formFields').innerHTML=`<div class="field full"><label>Projeto</label><select name="projectId" required><option value="">Selecione o projeto</option>${state.data.projects.map(project=>`<option value="${project.id}" ${project.id===value('projectId')?'selected':''}>${project.code||'Projeto'} · ${project.name}</option>`).join('')}</select></div><div class="field"><label>Tipo de gasto</label><select name="kind">${executionKinds.map(kind=>`<option ${kind===value('kind','Mão de obra')?'selected':''}>${kind}</option>`).join('')}</select></div><div class="field"><label>Data</label><input name="date" type="date" value="${value('date',todayInput())}" required></div><div class="field"><label>Colaborador / fornecedor</label><input name="person" value="${value('person')}" placeholder="Ex.: Valdemir ou fornecedor"></div><div class="field"><label>Horas / quantidade</label><input name="quantity" type="number" min="0" step="0.5" value="${value('quantity')}" placeholder="Ex.: 8"></div><div class="field"><label>Valor (R$)</label><input name="amount" type="number" min="0" step="0.01" value="${value('amount')}" required></div><div class="field full"><label>Descrição</label><textarea name="description" required placeholder="Ex.: diária técnica de instalação, compra de conectores ou frete.">${value('description')}</textarea></div>`;$('#recordDialog').showModal()}
function execution(){const entries=[...(state.data.executionEntries||[])].sort((a,b)=>String(b.date).localeCompare(String(a.date))),total=entries.reduce((sum,entry)=>sum+Number(entry.amount||0),0),labor=entries.filter(entry=>entry.kind==='Mão de obra').reduce((sum,entry)=>sum+Number(entry.amount||0),0),material=entries.filter(entry=>entry.kind==='Material de execução').reduce((sum,entry)=>sum+Number(entry.amount||0),0),rows=entries.map(entry=>{const project=state.data.projects.find(item=>item.id===entry.projectId);return `<tr><td>${entry.date?new Date(entry.date+'T12:00:00').toLocaleDateString('pt-BR'):'—'}</td><td><div class="entity">${project?.name||'Projeto removido'}</div><div class="subtext">${clientName(project?.clientId)}</div></td><td>${badge(entry.kind)}</td><td>${entry.person||'—'}</td><td>${entry.quantity||'—'}</td><td>${money(entry.amount)}</td><td><div class="entity">${entry.description}</div></td><td><button class="button secondary" data-exec-edit="${entry.id}">Editar</button></td></tr>`});const projectRows=state.data.projects.map(project=>{const metric=executionMetrics(project.id),limit=Number(project.cost||0),balance=limit-metric.total;return `<tr><td><div class="entity">${project.name}</div><div class="subtext">${clientName(project.clientId)}</div></td><td>${money(limit)}</td><td>${money(metric.labor)}</td><td>${money(metric.total)}</td><td class="${balance<0?'down':''}">${money(balance)}</td></tr>`});return heading('Execução e mão de obra','Registre o custo real do campo. Cada lançamento entra automaticamente no Financeiro e alimenta os indicadores do BI.','execution')+`<div class="module-toolbar"><button class="button primary" data-execution-entry>+ Registrar gasto</button><span class="subtext">Mão de obra, materiais, fretes e terceirizados por projeto.</span></div><div class="kpi-grid"><div class="kpi"><div class="kpi-top">Gasto de execução</div><div class="kpi-value">${money(total)}</div><div class="kpi-note">lançamentos registrados</div></div><div class="kpi"><div class="kpi-top">Mão de obra</div><div class="kpi-value">${money(labor)}</div><div class="kpi-note">diárias, horas e equipe</div></div><div class="kpi"><div class="kpi-top">Materiais de execução</div><div class="kpi-value">${money(material)}</div><div class="kpi-note">itens usados no campo</div></div></div><section class="card"><div class="card-head"><div><h3>Controle por projeto</h3><p class="subtext">Compare o gasto executado com o custo previsto do projeto.</p></div></div>${table(['Projeto','Custo previsto','Mão de obra','Executado','Saldo previsto'],projectRows)}</section><section class="card"><div class="card-head"><div><h3>Lançamentos de campo</h3><p class="subtext">Os lançamentos ficam disponíveis também no Financeiro como despesas realizadas.</p></div></div>${entries.length?table(['Data','Projeto','Tipo','Responsável','Qtd.','Valor','Descrição',''],rows):'<div class="empty">Ainda não há gastos de execução. Registre a primeira diária, material ou frete.</div>'}</section>`}
views.execution=execution;
const executionSaveRecord=saveRecord;saveRecord=(kind,data,editId='')=>{if(kind==='executionEntry'){const existing=editId?state.data.executionEntries.find(item=>item.id===editId):null,amount=Number(data.amount||0),record={id:existing?.id||uid('exec'),projectId:data.projectId,kind:data.kind,date:data.date,person:data.person||'',quantity:data.quantity||'',amount,description:data.description||'',financialEntryId:existing?.financialEntryId||uid('fin-exec')};if(existing)Object.assign(existing,record);else state.data.executionEntries.unshift(record);if(!Array.isArray(state.data.financialEntries))state.data.financialEntries=[];const project=state.data.projects.find(item=>item.id===record.projectId),financial={id:record.financialEntryId,type:'Despesa',status:'Realizado',amount,date:record.date,category:executionFinanceCategory(record.kind),responsible:record.person,clientId:project?.clientId||'',projectId:record.projectId,description:`[Execução] ${record.description}`},linked=state.data.financialEntries.find(item=>item.id===record.financialEntryId);if(linked)Object.assign(linked,financial);else state.data.financialEntries.unshift(financial);persist();render();toast('Gasto de execução salvo e enviado ao Financeiro.');return}return executionSaveRecord(kind,data,editId)};
