function openProjectEditor(id){const project=state.data.projects.find(item=>item.id===id);if(!project)return;$('#dialogTitle').textContent=`Editar projeto · ${project.name}`;$('#recordForm').dataset.kind='projectEdit';$('#recordForm').dataset.editId=id;$('#saveButton').textContent='Salvar projeto';$('#formFields').innerHTML=`<div class="field full"><label>Nome do projeto</label><input name="name" value="${project.name||''}" required></div><div class="field"><label>Código</label><input name="code" value="${project.code||''}"></div><div class="field"><label>Cliente</label><select name="clientId" required>${state.data.clients.map(client=>`<option value="${client.id}" ${client.id===project.clientId?'selected':''}>${client.name}</option>`).join('')}</select></div><div class="field"><label>Responsável</label><input name="manager" value="${project.manager||''}"></div><div class="field"><label>Etapa técnica</label><select name="technicalStage">${['Projeto técnico','Cabeamento','Instalação','Entrega'].map(stage=>`<option ${stage===project.technicalStage?'selected':''}>${stage}</option>`).join('')}</select></div><div class="field"><label>Situação</label><select name="status">${['Planejamento','Em execução','Bloqueado','Concluído','Entregue','Cancelado'].map(status=>`<option ${status===project.status?'selected':''}>${status}</option>`).join('')}</select></div><div class="field"><label>Progresso (%)</label><input name="progress" type="number" min="0" max="100" value="${Number(project.progress||0)}" required></div><div class="field"><label>Valor aprovado (R$)</label><input name="budget" type="number" min="0" step="0.01" value="${Number(project.budget||0)}"></div><div class="field"><label>Custo previsto (R$)</label><input name="cost" type="number" min="0" step="0.01" value="${Number(project.cost||0)}"></div><div class="field"><label>Prazo</label><input name="due" value="${project.due||''}" placeholder="Ex.: 2026-09-15"></div>`;$('#recordDialog').showModal()}
function deleteProject(id){const project=state.data.projects.find(item=>item.id===id);if(!project)return;const message=`Excluir o projeto “${project.name}”?\n\nSerão removidos também tarefas, compromissos, instalação, OS, relatórios, checklist, entrega, lista de obra, gastos de execução, lançamentos financeiros e avaliações vinculados.`;if(!confirm(message))return;const before=structuredClone(state.data),remove=list=>Array.isArray(list)?list.filter(item=>item.projectId!==id):[];state.data.projects=state.data.projects.filter(item=>item.id!==id);state.data.tasks=remove(state.data.tasks);state.data.appointments=(state.data.appointments||[]).filter(item=>item.projectId!==id);state.data.installations=remove(state.data.installations);state.data.serviceOrders=remove(state.data.serviceOrders);state.data.serviceReports=remove(state.data.serviceReports);state.data.projectChecklists=remove(state.data.projectChecklists);state.data.projectDeliveries=remove(state.data.projectDeliveries);state.data.supportTickets=remove(state.data.supportTickets);state.data.equipmentHistory=remove(state.data.equipmentHistory);state.data.purchaseItems=remove(state.data.purchaseItems);state.data.financialEntries=remove(state.data.financialEntries);state.data.executionEntries=remove(state.data.executionEntries);state.data.evaluations=remove(state.data.evaluations);state.selectedProject=null;state.view='projects';persist();render();offerUndo(`Projeto ${project.name} e seus vínculos foram excluídos.`,before)}
const projectEditSaveRecord=saveRecord;saveRecord=(kind,data,editId='')=>{if(kind==='projectEdit'){const project=state.data.projects.find(item=>item.id===editId);if(!project)return;Object.assign(project,{name:data.name,code:data.code,clientId:data.clientId,manager:data.manager,technicalStage:data.technicalStage,status:data.status,progress:Math.max(0,Math.min(100,Number(data.progress||0))),budget:Number(data.budget||0),cost:Number(data.cost||0),due:data.due||''});(state.data.installations||[]).filter(item=>item.projectId===editId).forEach(item=>Object.assign(item,{clientId:data.clientId,lead:data.manager,stage:data.technicalStage,progress:project.progress,status:data.status,due:project.due}));persist();render();toast('Projeto atualizado em todas as áreas vinculadas.');return}return projectEditSaveRecord(kind,data,editId)};
