document.addEventListener('click',event=>{const edit=event.target.closest('[data-project-edit]'),remove=event.target.closest('[data-project-delete]');if(edit){event.stopPropagation();openProjectEditor(edit.dataset.projectEdit)}if(remove){event.stopPropagation();deleteProject(remove.dataset.projectDelete)}});
