const agendaReportOpenItem=openAgendaItem;openAgendaItem=index=>{agendaReportOpenItem(index);const item=quickAgendaEntries[index];if(item?.kind!=='appointment'||!item.projectId)return;const appointment=state.data.appointments.find(entry=>entry.id===item.id),actions=$('#agendaItemContent .quick-actions');if(!appointment||!actions||actions.querySelector('[data-agenda-report]'))return;const report=state.data.serviceReports.find(entry=>entry.appointmentId===appointment.id),button=document.createElement('button');button.type='button';button.className='button primary';button.dataset.agendaReport=appointment.id;button.textContent=report?'Registrar novo relatório':'Registrar relatório';button.onclick=()=>openAgendaServiceReport(appointment);actions.insertBefore(button,actions.querySelector('[data-item-edit]'))};
const agendaReportSaveRecord=saveRecord;saveRecord=(kind,data,editId='')=>{if(kind==='agendaServiceReport'){if(!Array.isArray(state.data.serviceReports))state.data.serviceReports=[];const appointment=state.data.appointments.find(item=>item.id===data.appointmentId),report={id:uid('rpt'),projectId:data.projectId,appointmentId:data.appointmentId,date:data.date,technician:data.technician,execution:data.execution,status:data.status,tests:data.tests||'',pending:data.pending||'',nextActionDate:data.nextActionDate||'',media:data.media||'[]'};state.data.serviceReports.unshift(report);if(appointment){appointment.reportId=report.id;appointment.reportStatus=data.status;appointment.reportedAt=new Date().toISOString()}persist();render();toast('Relatório salvo no projeto e vinculado ao compromisso da agenda.');return}return agendaReportSaveRecord(kind,data,editId)};
