function addPurchaseMergeButton(){if(state.view!=='purchases'||document.querySelector('[data-purchase-merge]'))return;const toolbar=document.querySelector('[data-purchase-add]')?.parentElement;if(!toolbar)return;const button=document.createElement('button');button.type='button';button.className='button secondary';button.dataset.purchaseMerge='';button.textContent='Unificar repetidos';button.onclick=()=>{const before=structuredClone(state.data),merged=mergeDuplicatePurchaseItems();if(!merged){toast('Nenhum item repetido encontrado.');return}persist();render();offerUndo(`${merged} item(ns) repetido(s) unificado(s).`,before);toast(`${merged} item(ns) repetido(s) unificado(s).`)};toolbar.insertBefore(button,toolbar.firstChild)}
const purchaseSaveRecord=saveRecord;saveRecord=(kind,data,editId='')=>{if(kind==='purchaseItem'){const record={id:editId||uid('buy'),projectId:data.projectId,name:data.name,room:data.room||'',qty:Number(data.qty||0),unit:data.unit||'un',status:data.status||'Planejado',supplier:data.supplier||'',note:data.note||''};const index=state.data.purchaseItems.findIndex(item=>item.id===editId);if(index>=0)state.data.purchaseItems[index]={...state.data.purchaseItems[index],...record};else state.data.purchaseItems.unshift(record);persist();render();toast(editId?'Item da obra atualizado.':'Item adicionado à lista de obra.');return}return purchaseSaveRecord(kind,data,editId)};
