// Cadastro comercial: os dados de contato são a base obrigatória; o restante amadurece durante o atendimento.
function openCommercialOpportunity(editId='',prefill={}){const current=editId?state.data.opportunities.find(item=>item.id===editId):null,value=(key,fallback='')=>prefill[key]??current?.[key]??fallback,actor=localStorage.getItem('proelium-current-actor')||'';$('#dialogTitle').textContent=current?'Editar oportunidade':'Novo registro comercial';$('#recordForm').dataset.kind='opportunity';$('#recordForm').dataset.editId=editId;$('#saveButton').textContent=current?'Salvar oportunidade':'Criar oportunidade';$('#formFields').innerHTML=`<div class="field full"><p class="subtext"><strong>Dados essenciais</strong> · cliente, pessoa de contato, telefone, e-mail e responsável precisam estar preenchidos.</p></div><div class="field"><label>Cliente / empresa *</label><input name="company" autocomplete="organization" value="${value('company')}" placeholder="Nome da pessoa ou empresa" required></div><div class="field"><label>Pessoa de contato *</label><input name="contact" autocomplete="name" value="${value('contact')}" placeholder="Nome de quem falou com a equipe" required></div><div class="field"><label>Telefone *</label><input name="phone" type="tel" inputmode="tel" autocomplete="tel" value="${value('phone')}" placeholder="(11) 99999-9999" required></div><div class="field"><label>E-mail *</label><input name="email" type="email" inputmode="email" autocomplete="email" value="${value('email')}" placeholder="cliente@exemplo.com" required></div><div class="field full"><button type="button" class="button secondary" id="importDeviceContact">Importar contato do aparelho</button><small class="subtext">Disponível em navegadores compatíveis; no iPhone ou computador o preenchimento continua manual.</small></div><div class="field"><label>Responsável pelo atendimento *</label><select name="owner" required><option value="">Selecione</option>${(state.data.collaborators||[]).map(person=>`<option ${person.name===value('owner',actor)?'selected':''}>${person.name}</option>`).join('')}</select></div><div class="field"><label>Etapa atual</label><select name="stage">${['Novo contato','Qualificação','Visita','Orçamento'].map(stage=>`<option ${stage===value('stage','Novo contato')?'selected':''}>${stage}</option>`).join('')}</select></div><div class="field"><label>Origem do contato</label><select name="source"><option value="">Ainda não informado</option>${['Indicação','Instagram','Site','Telefone','Visita','Loja parceira','Outro'].map(source=>`<option ${source===value('source')?'selected':''}>${source}</option>`).join('')}</select></div><div class="field"><label>Próxima ação</label><input name="nextAction" value="${value('nextAction')}" placeholder="Ex.: agendar visita técnica"></div><div class="field"><label>Prazo da próxima ação</label><input name="nextDue" type="date" value="${value('nextDue')}"></div><div class="field"><label>Valor estimado (R$)</label><input name="estimatedValue" type="number" min="0" step="0.01" value="${value('estimatedValue',0)}"></div><div class="field"><label>Motivo de perda</label><input name="lossReason" value="${value('lossReason')}" placeholder="Preencher apenas se perdido"></div>`;const importButton=$('#importDeviceContact');importButton.onclick=async()=>{if(!navigator.contacts?.select){toast('Importação de contatos não é suportada neste aparelho. Preencha os dados manualmente.');return}try{const [contact]=await navigator.contacts.select(['name','tel','email'],{multiple:false});if(!contact)return;const fields=$('#recordForm').elements;if(contact.name?.[0])fields.company.value=contact.name[0],fields.contact.value=contact.name[0];if(contact.tel?.[0])fields.phone.value=contact.tel[0];if(contact.email?.[0])fields.email.value=contact.email[0];toast('Contato importado. Confira os dados antes de salvar.')}catch(error){if(error.name!=='AbortError')toast('Não foi possível importar o contato.')}};$('#recordDialog').showModal()}
const commercialOpportunityOpenForm=openForm;openForm=(kind,editId='',prefill={})=>kind==='opportunity'?openCommercialOpportunity(editId,prefill):commercialOpportunityOpenForm(kind,editId,prefill);
const commercialOpportunitySaveRecord=saveRecord;saveRecord=(kind,data,editId='')=>{if(kind==='opportunity'){const required=['company','contact','phone','email','owner'];if(required.some(field=>!String(data[field]||'').trim())){toast('Preencha cliente, contato, telefone, e-mail e responsável.');return}if(String(data.phone).replace(/\D/g,'').length<10){toast('Informe um telefone válido com DDD.');return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(data.email).trim())){toast('Informe um e-mail válido.');return}}return commercialOpportunitySaveRecord(kind,data,editId)};

// O ambiente é uma visão interna do orçamento, não um cadastro separado do cliente.
const quoteRoomFilterView=views.quoteDetail;views.quoteDetail=()=>{const quote=state.data.quotes.find(item=>item.id===state.selectedQuote),rooms=quote?(state.data.quoteRooms||[]).filter(room=>room.quoteId===quote.id):[],selected=state.quoteRoomFilterQuote===quote?.id?state.quoteRoomFilter||'all':'all',summary=`<section class="card quote-room-filter"><div class="card-head"><div><h3>Ambientes deste orçamento</h3><p class="subtext">Cada ambiente usa os itens deste orçamento para formar custo, venda, desconto e margem.</p></div></div><div class="module-toolbar"><button class="button secondary ${selected==='all'?'active':''}" data-quote-room-filter="all">Todos os ambientes</button>${rooms.map(room=>{const values=quoteRoomTotals(room);return `<button class="button secondary ${selected===room.id?'active':''}" data-quote-room-filter="${room.id}">${room.name} · ${money(values.price)}</button>`}).join('')}</div></section>`;return quoteRoomFilterView().replace('<div class="quote-analysis card">',summary+'<div class="quote-analysis card">')};
const quoteRoomFilterRender=render;render=()=>{quoteRoomFilterRender();if(state.view!=='quoteDetail')return;const quote=state.data.quotes.find(item=>item.id===state.selectedQuote),selected=state.quoteRoomFilterQuote===quote?.id?state.quoteRoomFilter||'all':'all';document.querySelectorAll('.room-grid .room-card').forEach(card=>{const room=(state.data.quoteRooms||[]).find(item=>item.quoteId===quote?.id&&item.name===card.querySelector('h3')?.textContent);card.hidden=selected!=='all'&&room?.id!==selected});document.querySelectorAll('[data-quote-room-filter]').forEach(button=>button.onclick=()=>{state.quoteRoomFilterQuote=quote?.id;state.quoteRoomFilter=button.dataset.quoteRoomFilter;render()})};

// Cliente só pode nascer da conclusão do Comercial ou da aprovação de orçamento.
const commercialOnlyClientsView=views.clients;views.clients=()=>commercialOnlyClientsView().replace(/<button class="button primary" data-add="client">[^<]+<\/button>/,'');
const commercialFlowView=views.commercial;views.commercial=()=>{const converted=state.data.opportunities.filter(item=>item.stage==='Ganho'&&state.data.clients.some(client=>client.name.toLowerCase()===item.company.toLowerCase())).length;const base=commercialFlowView().replace(/(<div class="kpi-top">Ganhas<\/div><div class="kpi-value">)\d+(<\/div><div class="kpi-note">)convertidas em cliente(<\/div>)/,`$1${converted}$2clientes criados$3`).replace(/<button class="link-button" data-convert-opportunity="([^"]+)">Converter em cliente<\/button>/g,(match,id)=>{const item=state.data.opportunities.find(opportunity=>opportunity.id===id);return item?.stage==='Orçamento'?`<button class="link-button" data-convert-opportunity="${id}">Concluir como ganho e criar cliente</button>`:''}),finished=state.data.opportunities.filter(item=>['Ganho','Perdido'].includes(item.stage));return base+`<section class="card commercial-history"><div class="card-head"><div><h3>Oportunidades concluídas</h3><p class="subtext">Registros continuam visíveis depois da conclusão comercial.</p></div></div>${finished.length?table(['Cliente / oportunidade','Resultado','Responsável','Próxima ação',''],finished.map(item=>{const client=state.data.clients.find(entry=>entry.name.toLowerCase()===item.company.toLowerCase());return `<tr><td><div class="entity">${item.company}</div><div class="subtext">${item.contact} · ${item.phone}</div></td><td>${badge(item.stage)}</td><td>${item.owner||'—'}</td><td>${client?'<span class="subtext">Cliente já criado</span>':item.stage==='Ganho'?`<button class="button secondary" data-convert-opportunity="${item.id}">Criar cliente</button>`:item.lossReason||'—'}</td><td></td></tr>`})):'<div class="empty">Nenhuma oportunidade concluída.</div>'}</section>`};
const commercialOnlyClientSave=saveRecord;saveRecord=(kind,data,editId='')=>{if(kind==='client'&&!editId){toast('Novos clientes devem entrar pelo Comercial e ser concluídos como ganho.');return}return commercialOnlyClientSave(kind,data,editId)};

// A entrada é controlada pelo Comercial, mas a lista de clientes mantém exclusão consciente e acessível.
const clientListDeleteView=views.clients;views.clients=()=>clientListDeleteView().replace(/(<tr class="clickable-row" data-client="([^"]+)">[\s\S]*?)<td>→<\/td><\/tr>/g,(match,row,id)=>`${row}<td><button class="button danger-outline client-delete" data-delete-client="${id}">Excluir</button></td></tr>`);
document.addEventListener('click',event=>{const button=event.target.closest('[data-delete-client]');if(!button)return;event.preventDefault();event.stopPropagation();deleteClient(button.dataset.deleteClient)},true);

// Menu orientado pelo caminho da informação. Os grupos serão a base dos futuros acessos por licença e perfil.
const menuFlowOrder=['dashboard','commercial','survey','quotes','clients','products','projects','processes','purchases','diagram','installations','agenda','tasks','operations','reports','equipment','execution','collaborators','quality','knowledge','finance','bi','biMarket','audit','users'];
const menuFlowGroup={dashboard:'Comercial',commercial:'Comercial',clients:'Comercial',products:'Comercial',projects:'Projeto e orçamento',processes:'Projeto e orçamento',purchases:'Projeto e orçamento',diagram:'Projeto e orçamento',installations:'Operação e pós-venda',agenda:'Operação e pós-venda',tasks:'Operação e pós-venda',operations:'Operação e pós-venda',reports:'Operação e pós-venda',equipment:'Operação e pós-venda',execution:'Operação e pós-venda',collaborators:'Pessoas e padrões',quality:'Pessoas e padrões',knowledge:'Pessoas e padrões',finance:'Gestão',bi:'Gestão',biMarket:'Gestão',audit:'Gestão'};
 menuFlowGroup.users='Gestão';
 if(!navItems.some(item=>item[0]==='users'))navItems.push(['users','♙','Usuários']);
 navItems.sort((left,right)=>menuFlowOrder.indexOf(left[0])-menuFlowOrder.indexOf(right[0]));
renderNav=()=>{let previousGroup='';const visible=navItems.filter(item=>canViewRole(item[0]));if(!canViewRole(state.view)&&state.view!=='dashboard')state.view='dashboard';$('#navigation').innerHTML=visible.map(([id,icon,label])=>{const group=menuFlowGroup[id]||'Outros',section=group===previousGroup?'':`<p class="nav-section">${group}</p>`;previousGroup=group;return `${section}<button class="nav-item ${state.view===id?'active':''}" data-view="${id}"><span class="nav-icon">${icon}</span>${label}</button>`}).join('')};
render();

// Oportunidades em tratamento podem ser removidas com confirmação e restauração imediata.
function deleteOpportunity(id){const opportunity=state.data.opportunities.find(item=>item.id===id);if(!opportunity)return;const quotes=state.data.quotes.filter(item=>item.opportunityId===id),approved=quotes.some(item=>quoteStatus(item)==='Aprovado');if(approved){toast('Esta oportunidade já gerou um orçamento aprovado. Preserve o histórico pelo cliente e projeto vinculados.');return}const quoteIds=quotes.map(item=>item.id),detail=quotes.length?`\n\nTambém será removido ${quotes.length===1?'o orçamento em elaboração vinculado':'os '+quotes.length+' orçamentos em elaboração vinculados'}, incluindo os ambientes.`:'';if(!confirm(`Excluir a oportunidade “${opportunity.company}”?${detail}`))return;const before=structuredClone(state.data);state.data.quoteRooms=state.data.quoteRooms.filter(item=>!quoteIds.includes(item.quoteId));state.data.procurementRequests=(state.data.procurementRequests||[]).filter(item=>!quoteIds.includes(item.quoteId));state.data.quotes=state.data.quotes.filter(item=>item.opportunityId!==id);state.data.opportunities=state.data.opportunities.filter(item=>item.id!==id);logAudit('Excluiu','Oportunidade',opportunity.company);persist();render();offerUndo(`Oportunidade ${opportunity.company} foi excluída.`,before)}
const opportunityDeleteView=views.commercial;views.commercial=()=>opportunityDeleteView().replace(/(<button class="link-button" data-advance-opportunity="([^"]+)">Avançar<\/button>)/g,(match,button,id)=>`${button}<button class="link-button opportunity-delete" data-delete-opportunity="${id}">Excluir</button>`);
document.addEventListener('click',event=>{const button=event.target.closest('[data-delete-opportunity]');if(!button)return;event.preventDefault();event.stopPropagation();deleteOpportunity(button.dataset.deleteOpportunity)},true);

// Recuperação comercial: a exclusão guarda somente a oportunidade e seus rascunhos vinculados.
// Assim, restaurar pela Auditoria não apaga mudanças posteriores de outros aparelhos.
if(!Array.isArray(state.data.recoveryLog))state.data.recoveryLog=[];
function saveOpportunityRecovery(opportunity,quotes,quoteIds){if(!Array.isArray(state.data.recoveryLog))state.data.recoveryLog=[];state.data.recoveryLog.unshift({id:uid('recovery'),type:'opportunity',label:opportunity.company,createdAt:new Date().toISOString(),actor:auditActor(),data:{opportunity:structuredClone(opportunity),quotes:structuredClone(quotes),rooms:structuredClone(state.data.quoteRooms.filter(item=>quoteIds.includes(item.quoteId))),procurement:structuredClone((state.data.procurementRequests||[]).filter(item=>quoteIds.includes(item.quoteId)))}});state.data.recoveryLog=state.data.recoveryLog.slice(0,50)}
function deleteOpportunity(id){const opportunity=state.data.opportunities.find(item=>item.id===id);if(!opportunity)return;const quotes=state.data.quotes.filter(item=>item.opportunityId===id),draftQuotes=quotes.filter(item=>quoteStatus(item)!=='Aprovado'),quoteIds=draftQuotes.map(item=>item.id),approvedCount=quotes.length-draftQuotes.length,detail=`${draftQuotes.length?`\n\nTambém será removido ${draftQuotes.length===1?'o orçamento em elaboração vinculado':'os '+draftQuotes.length+' orçamentos em elaboração vinculados'}, incluindo os ambientes.`:''}${approvedCount?`\n\n${approvedCount} orçamento(s) aprovado(s), cliente(s) e projeto(s) vinculados serão preservados.`:''}`;if(!confirm(`Excluir a oportunidade “${opportunity.company}”?${detail}`))return;saveOpportunityRecovery(opportunity,quotes,quoteIds);state.data.quoteRooms=state.data.quoteRooms.filter(item=>!quoteIds.includes(item.quoteId));state.data.procurementRequests=(state.data.procurementRequests||[]).filter(item=>!quoteIds.includes(item.quoteId));state.data.quotes=state.data.quotes.filter(item=>!quoteIds.includes(item.id));state.data.opportunities=state.data.opportunities.filter(item=>item.id!==id);logAudit('Excluiu','Oportunidade',`${opportunity.company} · recuperação disponível na Auditoria`);persist();render();toast(`Oportunidade ${opportunity.company} excluída. A recuperação está na Auditoria.`)}
function restoreOpportunityRecovery(id){const recovery=(state.data.recoveryLog||[]).find(item=>item.id===id&&item.type==='opportunity');if(!recovery)return;if(state.data.opportunities.some(item=>item.id===recovery.data.opportunity.id)){toast('Não foi possível restaurar: já existe uma oportunidade com este identificador.');return}if(!confirm(`Restaurar a oportunidade “${recovery.label}” e os rascunhos vinculados?`))return;state.data.opportunities.unshift(structuredClone(recovery.data.opportunity));(recovery.data.quotes||[]).forEach(item=>{if(!state.data.quotes.some(current=>current.id===item.id))state.data.quotes.push(structuredClone(item))});(recovery.data.rooms||[]).forEach(item=>{if(!state.data.quoteRooms.some(current=>current.id===item.id))state.data.quoteRooms.push(structuredClone(item))});(recovery.data.procurement||[]).forEach(item=>{if(!state.data.procurementRequests.some(current=>current.id===item.id))state.data.procurementRequests.push(structuredClone(item))});state.data.recoveryLog=state.data.recoveryLog.filter(item=>item.id!==id);logAudit('Restaurou','Oportunidade',recovery.label);persist();render();toast(`Oportunidade ${recovery.label} foi restaurada.`)}
const auditRecoveryView=views.audit;views.audit=()=>{const recoveries=(state.data.recoveryLog||[]).filter(item=>item.type==='opportunity'),section=`<section class="card"><div class="card-head"><div><h3>Recuperação de oportunidades</h3><p class="subtext">Itens excluídos que podem ser restaurados sem desfazer alterações posteriores.</p></div></div>${recoveries.length?table(['Oportunidade','Excluída em','Por','Ação'],recoveries.map(item=>`<tr><td><strong>${item.label}</strong></td><td>${new Date(item.createdAt).toLocaleString('pt-BR')}</td><td>${item.actor||'Usuário do dispositivo'}</td><td><button class="button secondary" data-recover-opportunity="${item.id}">Restaurar</button></td></tr>`)):'<div class="empty">Nenhuma oportunidade aguardando recuperação.</div>'}</section>`;return auditRecoveryView()+section};
document.addEventListener('click',event=>{const button=event.target.closest('[data-recover-opportunity]');if(!button)return;event.preventDefault();event.stopPropagation();restoreOpportunityRecovery(button.dataset.recoverOpportunity)},true);
render();

// Esta é a versão final do formulário comercial: importação só preenche telefone/e-mail.
const commercialManualFormBase=openCommercialOpportunityManualV2;openCommercialOpportunityManualV2=(editId='',prefill={})=>{commercialManualFormBase(editId,prefill);const importButton=$('#importDeviceContact');if(!importButton)return;importButton.onclick=async()=>{if(!navigator.contacts?.select){toast('Importação de contatos não é suportada neste aparelho. Preencha telefone e e-mail manualmente.');return}try{const [deviceContact]=await navigator.contacts.select(['name','tel','email'],{multiple:false});if(!deviceContact)return;const fields=$('#recordForm').elements,phone=Array.isArray(deviceContact.tel)?deviceContact.tel.find(Boolean):deviceContact.tel,email=Array.isArray(deviceContact.email)?deviceContact.email.find(Boolean):deviceContact.email;let imported=0;if(phone){fields.phone.value=phone;imported++}if(email){fields.email.value=email;imported++}toast(imported?'Telefone e e-mail importados. Confira antes de salvar.':'O contato selecionado não possui telefone nem e-mail.')}catch(error){if(error.name!=='AbortError')toast('Não foi possível importar o contato.')}}};
const finalCommercialOpenForm=openForm;openForm=(kind,editId='',prefill={})=>kind==='opportunity'?openCommercialOpportunityManualV2(editId,prefill):finalCommercialOpenForm(kind,editId,prefill);

// Complemento opcional para registrar de onde veio a oportunidade em mais detalhes.
const commercialSourceDetailFormBase=openCommercialOpportunityManualV2;openCommercialOpportunityManualV2=(editId='',prefill={})=>{commercialSourceDetailFormBase(editId,prefill);const source=$('#recordForm select[name="source"]');if(!source||$('#recordForm [name="sourceDetail"]'))return;const current=editId?state.data.opportunities.find(item=>item.id===editId):null,value=prefill.sourceDetail??current?.sourceDetail??'';source.closest('.field').insertAdjacentHTML('afterend',`<div class="field"><label>Descrição da origem (opcional)</label><input name="sourceDetail" value="${value}" placeholder="Ex.: indicação de João, Instagram da obra, feira"></div>`)};
const commercialSourceDetailSave=saveRecord;saveRecord=(kind,data,editId='')=>{const result=commercialSourceDetailSave(kind,data,editId);if(kind==='opportunity'&&data.sourceDetail!==undefined){const opportunity=editId?state.data.opportunities.find(item=>item.id===editId):state.data.opportunities[0];if(opportunity){opportunity.sourceDetail=data.sourceDetail.trim();persist();render()}}return result};
const commercialSourceDetailEdit=saveEditedRecord;saveEditedRecord=(kind,data,id)=>{const result=commercialSourceDetailEdit(kind,data,id);if(kind==='opportunity'&&data.sourceDetail!==undefined){const opportunity=state.data.opportunities.find(item=>item.id===id);if(opportunity){opportunity.sourceDetail=data.sourceDetail.trim();persist();render()}}return result};

// Acesso unitário a cada orçamento, sem depender da página Comercial.
function quotes(){const items=state.data.quotes||[],rows=items.map(quote=>{const rooms=(state.data.quoteRooms||[]).filter(room=>room.quoteId===quote.id),totals=quoteTotals(quote.id);return `<tr class="clickable-row" data-quote="${quote.id}"><td><div class="entity">${quote.title}</div><div class="subtext">${quote.id} · versão ${quote.version||1}</div></td><td>${quotePartyName(quote)}</td><td>${rooms.length}</td><td>${money(totals.price||quote.value||0)}</td><td>${badge(quoteStatus(quote))}</td><td>→</td></tr>`});return heading('Orçamentos','Acesse, acompanhe e revise cada proposta comercial de forma individual.')+`<div class="module-toolbar"><button class="button primary" data-add="quote">+ Novo orçamento</button><span class="subtext">${items.length} orçamento(s) registrado(s)</span></div>`+table(['Orçamento','Cliente / oportunidade','Ambientes','Total líquido','Situação',''],rows)}
views.quotes=quotes;validViews.add('quotes');if(!navItems.some(item=>item[0]==='quotes')){menuFlowGroup.quotes='Comercial';navItems.push(['quotes','▤','Orçamentos']);navItems.sort((left,right)=>menuFlowOrder.indexOf(left[0])-menuFlowOrder.indexOf(right[0]))}
const directQuoteDetailView=views.quoteDetail;views.quoteDetail=()=>directQuoteDetailView().replace('data-view="commercial">← Voltar para orçamentos','data-view="quotes">← Voltar para orçamentos');

// Movimentação de ativos: troca de local sem perder série, histórico ou vínculo técnico.
function openEquipmentMove(id){const asset=(state.data.equipment||[]).find(item=>item.id===id);if(!asset)return;$('#dialogTitle').textContent='Mover equipamento';$('#recordForm').dataset.kind='equipmentMove';$('#recordForm').dataset.editId=id;$('#saveButton').textContent='Registrar movimentação';$('#formFields').innerHTML=`<div class="field full"><label>Equipamento</label><input value="${equipmentLabel(asset)} · Série: ${asset.serial||'não informada'}" disabled></div><div class="field"><label>Local atual</label><input value="${asset.location||'Não informado'}" disabled></div><div class="field"><label>Novo local *</label><input name="location" value="${asset.location||''}" placeholder="Ex.: Sala, rack técnico, estoque" required></div><div class="field"><label>Data da movimentação *</label><input name="date" type="date" value="${todayInput()}" required></div><div class="field"><label>Motivo / observação</label><input name="note" placeholder="Ex.: remanejamento, troca de ambiente"></div>`;$('#recordDialog').showModal()}
const equipmentMoveView=views.equipment;views.equipment=()=>equipmentMoveView().replace(/(<button class="button secondary" data-edit-equipment="([^"]+)">Editar<\/button>)/g,(match,button,id)=>`${button} <button class="button secondary" data-move-equipment="${id}">Mover</button>`);
const equipmentMoveSave=saveRecord;saveRecord=(kind,data,editId='')=>{if(kind==='equipmentMove'){const asset=(state.data.equipment||[]).find(item=>item.id===editId);if(!asset)return;const previous=asset.location||'Local não informado',next=String(data.location||'').trim();if(!next){toast('Informe o novo local do equipamento.');return}if(next===previous){toast('Informe um local diferente para registrar a movimentação.');return}asset.location=next;addEquipmentHistory(asset.id,asset.clientId,'Movimentação',`${previous} → ${next}${data.note?` · ${data.note}`:''}`,data.date||todayInput());logAudit('Moveu','Equipamento',`${equipmentLabel(asset)} · ${previous} → ${next}`);persist();render();toast('Movimentação do equipamento registrada.');return}return equipmentMoveSave(kind,data,editId)};
